<?php
/** Favicons, app icons and PWA/Windows metadata (generated by `npm run icons` from resources/brand). */
$custom = (string) setting('favicon', '');
?>
<?php if ($custom): ?>
  <link rel="icon" href="<?= e(media_url($custom)) ?>">
<?php else: ?>
  <link rel="icon" href="<?= e(url('favicon.ico')) ?>" sizes="48x48">
  <link rel="icon" href="<?= e(url('favicon.svg')) ?>" type="image/svg+xml">
  <link rel="icon" type="image/png" sizes="32x32" href="<?= e(url('assets/icons/favicon-32x32.png')) ?>">
  <link rel="icon" type="image/png" sizes="16x16" href="<?= e(url('assets/icons/favicon-16x16.png')) ?>">
  <link rel="icon" type="image/png" sizes="96x96" href="<?= e(url('assets/icons/favicon-96x96.png')) ?>">
<?php endif ?>
  <link rel="apple-touch-icon" sizes="180x180" href="<?= e(url('apple-touch-icon.png')) ?>">
  <link rel="mask-icon" href="<?= e(url('assets/icons/safari-pinned-tab.svg')) ?>" color="#101D32">
  <link rel="manifest" href="<?= e(url('site.webmanifest')) ?>">
  <meta name="application-name" content="<?= e(company('short_name', company('name'))) ?>">
  <meta name="apple-mobile-web-app-title" content="<?= e(company('short_name', company('name'))) ?>">
  <meta name="msapplication-TileColor" content="#101D32">
  <meta name="msapplication-config" content="<?= e(url('browserconfig.xml')) ?>">
